We consider infinite countable first-order structures, their automorphism groups and the descriptive aspects of their representations. A representation $\mathcal{A}$ of such a structure is an instance of its isomorphism type in which the universe or domain of the structure is the set of natural numbers $\mathbb{N}$ and the constants, functions and relations of the structure are elements of $\mathbb{N}$, multi-variable functions from $\mathbb{N}$ to $\mathbb{N}$ and multi-place relations on $\mathbb{N}$, respectively.   Similarly, an automorphism of $\mathcal{A}$ or an isomorphism from $\mathcal{A}$ to $\mathcal{B}$ is a bijective function from $\mathbb{N}$ to $\mathbb{N}$ that preserves the evaluation of all constants, functions and relations.  We let $\operatorname{AUT}(\mathcal{A})$ denote the automorphism group of $\mathcal{A}$.

\begin{definition}\label{1.1}
  \begin{itemize}
  \item     $\mathcal{A}$ is \emph{computably $\operatorname{AUT}$-countable} if every automorphism of $\mathcal{A}$ is computable relative to $\mathcal{A}$.  
  \item  $\mathcal{A}$ is \emph{computably $\operatorname{AUT}$-countable on a cone} if there is a $C\subset\mathbb{N}$ such that whenever $\mathcal{B}$ is isomorphic to $\mathcal{A}$, every automorphism of $\mathcal{B}$ is computable relative to $\mathcal{B}\oplus C$.
  \end{itemize}
\end{definition}


\begin{definition}
  A function $f:\mathcal{A}\to\mathcal{A}$ is \emph{$\Sigma^{in}_1$-definable} in $\mathcal{A}$ relative to parameters
  $\bar{a}=(a_1,\dots,a_n)$ from $\mathcal{A}$ if there is a family of existential formulas $(\phi_i)_{i\in\mathbb{N}}$ such that for all $x$ and $y$ in $\mathcal{A}$, $f(x)=y$ if and only if there is an $i\in\mathbb{N}$ such that $\mathcal{A}\models\phi_i(\bar{a},x,y)$.
\end{definition}

\begin{question}\label{sec:question}\label{1.2}
  Is there a countable computably-represented structure $\mathcal{A}$ such that $\mathcal{A}$ is computably $\operatorname{AUT}$-countable on a cone and such that for any finite  set of parameters $\bar{a}$ in $\mathcal{A}$ there is an automorphism $\pi$ of $\mathcal{A}$ such that $\pi$ is not $\Sigma^{in}_1$-definable in $\mathcal{A}$ relative to the parameters $\bar{a}\cup \pi(\bar{a}),$ where $\pi(\bar{a})$ is the image of $\bar{a}$ under $\pi$.
\end{question}
